fields.InputDefinition:
{
  "goal": "Open the Integrations application. To reach it, open the application switcher dropdown next to the logo and SCROLL the full list (it is long) to find 'Integrations'; if it is not in the switcher, try the application cards on the Home page, or the 'Configure Apps' option to add/open it. In Integrations, view the Overview and verify it renders with KPI cards/activity (or a valid empty-state), no crash. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 45,
  "judgeValidationCriteria": [
    "The Integrations app is active and the Overview section is displayed",
    "The Overview shows KPI cards and/or an activity feed, or a clean empty-state placeholder",
    "No error messages, blank screens, or crash pages"
  ]
}
